#!/usr/bin/env bash
# Round 10 retention art (Cat Street, renovation sets, visitor nooks), ONE at a time via studio/bin/art.sh.
# usage: street.sh [name...]  (FORCE=1 to redo). Processed by proc_street.py.
cd /c/Users/Admin/Documents/Msjelly/studio/long-cat-out/art-src/r7
S="Art style (must match across the whole set): soft painterly 3D cartoon like a polished 2026 mobile game, smooth chunky rounded felt-toy shapes, clean soft shading and gentle gradients, NOT photorealistic, NOT flat vector, no outlines. Palette: sage green walls #689A8D, honey oak wood #BF7948 with darker oak #8E5530, ivory #FFF0D3, rust red #BD582F, warm cream #fff6e5. One warm sunlight from the upper right, soft shadows falling down-left. Absolutely no text, no letters, no numbers, no logo, no watermark."
K="Place every item on a flat solid pure magenta #ff00ff background with nothing else on it so it can be keyed out; no shadow on the background, items must not touch each other or the image edge."
G="Arrange as a clean grid with wide magenta gaps between items, each item fully visible and the same scale."
g(){ n=$1; shift; if [ -s "$n.png" ] && [ -z "$FORCE" ]; then echo "skip $n"; return; fi; echo "gen $n $(date +%T)"; timeout 600 /c/Users/Admin/Documents/Msjelly/studio/bin/art.sh "$(pwd -W)/$n.png" "$*" >/dev/null 2>&1; ls -la "$n.png" 2>&1 | awk '{print $5}'; }
W=("$@")
run(){ if [ ${#W[@]} -eq 0 ]; then return 0; fi; for w in "${W[@]}"; do [ "$w" = "$1" ] && return 0; done; return 1; }

run street_bg && g street_bg "Portrait 2:3 full-bleed game background, NO magenta: a cozy cobblestone town street seen straight from the front in warm late-afternoon light. Soft blue sky with puffy clouds in the top third, distant rooftops and round trees far behind, a wide plain cobbled street across the bottom quarter with a pavement strip, flower pots and an old lamp post at the far left and far right edges. The whole middle of the image is an EMPTY row of flat building plots ready for houses to be placed: no buildings in the centre, no characters. $S"
run street_shops_a && g street_shops_a "Three narrow two-storey storybook shop houses for a town of cats, straight front view, each a complete standalone building with its own roof and doorstep, all the same width and height: (1) a bakery with a warm cream facade, a striped peach awning, a blank bread-loaf shaped sign board with no lettering, loaves in the window; (2) a library with a sage green facade, tall arched windows full of books, a wooden door; (3) a florist with a rose-pink facade, flower boxes overflowing, a green awning, buckets of flowers by the door. Little cat-ear shapes on each roof. Left to right in one row. $K $S"
run street_shops_b && g street_shops_b "Three narrow two-storey storybook shop houses for a town of cats, straight front view, each a complete standalone building with its own roof and doorstep, all the same width and height: (1) a tea house with a teal facade, round paper lanterns and a little teapot sign without lettering; (2) a toy shop with a sunny yellow facade, yarn balls and toy mice in the window; (3) a music shop with a plum purple facade, a gramophone and a small piano in the window. Little cat-ear shapes on each roof. Left to right in one row. $K $S"
run keepers && g keepers "Six chubby cute felt-toy cats, the shopkeepers of a cat town, full body sitting, front 3/4 view, same scale: (1) cream cat in a white baker hat and apron holding a croissant; (2) grey tabby with round glasses holding a small book; (3) calico with a flower crown holding a tulip; (4) black-and-white tuxedo cat holding a teacup; (5) ginger kitten in a striped beanie holding a toy mouse; (6) Siamese cat with a red bow tie holding a tiny violin. Arrange as 2 rows x 3 columns. $K $G $S"
run reno && g reno "Room renovation decor sets for a cozy cat cafe: three themed sets, each set is one row of two items: a wide festive garland to hang across a ceiling (left) and a large oval floor rug seen from a slightly raised angle (right). Row 1 autumn lantern theme: garland of small orange paper lanterns and maple leaves; rug with a warm orange and rust leaf pattern. Row 2 cocoa snow theme: garland of white felt snowflakes and little blue mittens; pale blue rug with a snowflake pattern. Row 3 blossom theme: garland of pink cherry blossoms and paper butterflies; soft pink rug with a flower pattern. 3 rows x 2 columns. $K $G $S"
run nooks && g nooks "Three cozy visitor nooks for guest cats, each a cushioned round cat bed with one matching decoration, seen from a slightly raised 3/4 angle, same scale: (1) autumn: an orange knitted bed with a small glowing paper lantern beside it; (2) winter: a light-blue fluffy bed with a mug of cocoa and a snowflake pillow; (3) spring: a pink petal-shaped bed with a small pot of blossoms. Empty beds, no cats. Left to right in one row. $K $S"
run apprentices && g apprentices "Six tiny cute felt-toy KITTENS, the apprentices of six cat shopkeepers, full body sitting, front 3/4 view, same scale, clearly smaller and rounder than adult cats with big heads: (1) a cream kitten in a small white baker hat with a flour-dusted nose holding a tiny bread roll; (2) a grey tabby kitten with a red reading scarf hugging a small stack of two books; (3) a calico kitten with a daisy behind one ear holding a little watering can; (4) a tuxedo kitten in a tiny teal apron holding a sugar cube; (5) a ginger kitten with a propeller cap holding a ball of blue yarn; (6) a Siamese kitten with a yellow neckerchief holding a small drum. Arrange as 2 rows x 3 columns. $K $G $S"
echo "all done $(date +%T)"
